query GetLatestResults(
	$searchFilters: SearchFilters!
	$pagination: Pagination!
) {
	search(filters: $searchFilters, pagination: $pagination) {
		results {
			id
			name
			candidates {
				displayName
				nVotes
				pctCandidateVotes
				candidate {
					pseudocandidate
				}
				isWinner
			}
			eventTypeDisplayName
			office {
				name
			}
			event {
				startDate
			}
			division {
				displayName
			}
		}
	}
}
